1	// Offline route resolution: match a request against configured route prefixes
2	// and join the remainder onto the upstream base path without any network I/O.
3	package contractsentinel
4	
5	import (
6		"encoding/json"
7		"fmt"
8		"net/url"
9		"sort"
10		"strings"
11	)
12	
13	// Route is one configured route: an id, accepted methods, a path prefix and
14	// the upstream URL requests on that route are forwarded to.
15	type Route struct {
16		ID         string   `json:"id"`
17		Methods    []string `json:"methods"`
18		PathPrefix string   `json:"pathPrefix"`
19		Upstream   string   `json:"upstream"`
20	}
21	
22	// Config is the resolve configuration: a flat array of routes.
23	type Config struct {
24		Routes []Route `json:"routes"`
25	}
26	
27	// Request is one resolution request: an HTTP method and a request target
28	// (path with an optional raw query string).
29	type Request struct {
30		Method string `json:"method"`
31		Target string `json:"target"`
32	}
33	
34	// Resolution is the successful result of matching a request.
35	type Resolution struct {
36		RouteID     string `json:"routeId"`
37		UpstreamURL string `json:"upstreamURL"`
38	}
39	
40	// Failure carries a stable machine-readable code and a human-readable reason.
41	type Failure struct {
42		Code       string   `json:"code"`
43		Reason     string   `json:"reason"`
44		Candidates []string `json:"candidates,omitempty"`
45	}
46	
47	func (f *Failure) Error() string { return f.Code + ": " + f.Reason }
48	
49	func failuref(code, format string, args ...any) *Failure {
50		return &Failure{Code: code, Reason: fmt.Sprintf(format, args...)}
51	}
52	
53	// ParseConfig parses and fully validates the route configuration.
54	func ParseConfig(data []byte) (*Config, *Failure) {
55		var cfg Config
56		if err := json.Unmarshal(data, &cfg); err != nil {
57			return nil, failuref("invalid_config", "config is not valid JSON: %v", err)
58		}
59		if f := cfg.validate(); f != nil {
60			return nil, f
61		}
62		return &cfg, nil
63	}
64	
65	func (cfg *Config) validate() *Failure {
66		seenIDs := make(map[string]int, len(cfg.Routes))
67		for i := range cfg.Routes {
68			route := &cfg.Routes[i]
69			loc := fmt.Sprintf("route %d", i+1)
70			if route.ID == "" {
71				return failuref("invalid_config", "%s: id must be non-empty", loc)
72			}
73			if first, ok := seenIDs[route.ID]; ok {
74				return failuref("invalid_config", "%s: duplicate id %q (already used by route %d)", loc, route.ID, first)
75			}
76			seenIDs[route.ID] = i + 1
77	
78			if len(route.Methods) == 0 {
79				return failuref("invalid_config", "%s (id %q): methods must be a non-empty array", loc, route.ID)
80			}
81			for _, method := range route.Methods {
82				switch {
83				case method == "":
84					return failuref("invalid_config", "%s (id %q): methods must not contain empty entries", loc, route.ID)
85				case method == "*":
86					// Wildcard matching any legal method.
87				case !isToken(method):
88					return failuref("invalid_config", "%s (id %q): invalid method %q", loc, route.ID, method)
89				}
90			}
91	
92			if f := validatePrefix(route.PathPrefix, loc, route.ID); f != nil {
93				return f
94			}
95			if f := validateUpstream(route.Upstream, loc, route.ID); f != nil {
96				return f
97			}
98		}
99		return nil
100	}
101	
102	func validatePrefix(prefix, loc, id string) *Failure {
103		switch {
104		case prefix == "" || prefix[0] != '/':
105			return failuref("invalid_config", "%s (id %q): pathPrefix must start with /", loc, id)
106		case prefix != "/" && strings.HasSuffix(prefix, "/"):
107			return failuref("invalid_config", "%s (id %q): pathPrefix must not end with / except for root", loc, id)
108		case strings.ContainsAny(prefix, "?#"):
109			return failuref("invalid_config", "%s (id %q): pathPrefix must not contain a query string or fragment", loc, id)
110		case !validPercentEscapes(prefix):
111			return failuref("invalid_config", "%s (id %q): pathPrefix contains an invalid percent escape", loc, id)
112		}
113		return nil
114	}
115	
116	func validateUpstream(raw, loc, id string) *Failure {
117		if strings.ContainsAny(raw, "?#") {
118			return failuref("invalid_config", "%s (id %q): upstream must not contain a query string or fragment", loc, id)
119		}
120		u, err := url.Parse(raw)
121		if err != nil {
122			return failuref("invalid_config", "%s (id %q): upstream is not a valid URL: %v", loc, id, err)
123		}
124		if u.Scheme != "http" && u.Scheme != "https" {
125			return failuref("invalid_config", "%s (id %q): upstream must be an absolute http or https URL", loc, id)
126		}
127		if u.Host == "" {
128			return failuref("invalid_config", "%s (id %q): upstream must include a host", loc, id)
129		}
130		return nil
131	}
132	
133	// ParseRequest parses and validates one JSON request.
134	func ParseRequest(data []byte) (*Request, *Failure) {
135		var req Request
136		if err := json.Unmarshal(data, &req); err != nil {
137			return nil, failuref("invalid_request", "request is not valid JSON: %v", err)
138		}
139		switch {
140		case req.Method == "":
141			return nil, failuref("invalid_request", "method is required")
142		case !isToken(req.Method):
143			return nil, failuref("invalid_request", "method %q is not a legal HTTP method", req.Method)
144		}
145		switch {
146		case req.Target == "" || req.Target[0] != '/':
147			return nil, failuref("invalid_request", "target must start with /")
148		case strings.Contains(req.Target, "#"):
149			return nil, failuref("invalid_request", "target must not contain a fragment")
150		case !validPercentEscapes(req.Target):
151			return nil, failuref("invalid_request", "target contains an invalid percent escape")
152		}
153		return &req, nil
154	}
155	
156	// Resolve matches a validated request against a validated configuration and
157	// computes the upstream URL. Failure codes are route_not_found and
158	// route_conflict.
159	func Resolve(cfg *Config, req *Request) (*Resolution, *Failure) {
160		path := req.Target
161		if i := strings.IndexByte(path, '?'); i >= 0 {
162			path = path[:i]
163		}
164	
165		type candidate struct {
166			route    *Route
167			concrete bool
168		}
169		var matched []candidate
170		for i := range cfg.Routes {
171			route := &cfg.Routes[i]
172			concrete, wildcard := methodMatch(route.Methods, req.Method)
173			if !concrete && !wildcard {
174				continue
175			}
176			if !prefixMatch(route.PathPrefix, path) {
177				continue
178			}
179			matched = append(matched, candidate{route, concrete})
180		}
181		if len(matched) == 0 {
182			return nil, failuref("route_not_found", "no route matches %s %s", req.Method, path)
183		}
184	
185		// Longest prefix wins.
186		bestLen := 0
187		for _, c := range matched {
188			if n := len(c.route.PathPrefix); n > bestLen {
189				bestLen = n
190			}
191		}
192		winners := matched[:0]
193		for _, c := range matched {
194			if len(c.route.PathPrefix) == bestLen {
195				winners = append(winners, c)
196			}
197		}
198	
199		// Among equal prefixes a concrete method beats the wildcard.
200		var concrete []candidate
201		for _, c := range winners {
202			if c.concrete {
203				concrete = append(concrete, c)
204			}
205		}
206		if len(concrete) > 0 {
207			winners = concrete
208		}
209		if len(winners) > 1 {
210			ids := make([]string, 0, len(winners))
211			for _, c := range winners {
212				ids = append(ids, c.route.ID)
213			}
214			sort.Strings(ids)
215			f := failuref("route_conflict", "multiple routes match %s %s", req.Method, path)
216			f.Candidates = ids
217			return nil, f
218		}
219	
220		upstreamURL, f := joinUpstream(winners[0].route, path, req.Target)
221		if f != nil {
222			return nil, f
223		}
224		return &Resolution{RouteID: winners[0].route.ID, UpstreamURL: upstreamURL}, nil
225	}
226	
227	// methodMatch reports whether the method list matches the request method
228	// concretely (an exact, case-sensitive entry) or via the "*" wildcard.
229	func methodMatch(methods []string, method string) (concrete, wildcard bool) {
230		for _, m := range methods {
231			switch {
232			case m == "*":
233				wildcard = true
234			case m == method:
235				concrete = true
236			}
237		}
238		return concrete, wildcard
239	}
240	
241	// prefixMatch matches raw encoded paths on segment boundaries: "%2F" is never
242	// treated as a separator and the root prefix matches every origin-path.
243	func prefixMatch(prefix, path string) bool {
244		if prefix == "/" {
245			return true
246		}
247		if path == prefix {
248			return true
249		}
250		return strings.HasPrefix(path, prefix) && path[len(prefix)] == '/'
251	}
252	
253	// joinUpstream strips the route prefix from the request path and joins the
254	// remainder onto the upstream base path with exactly one slash at the
255	// junction. The base path and raw query string are carried over byte for
256	// byte: joining never re-encodes, reorders or drops anything.
257	func joinUpstream(route *Route, path, target string) (string, *Failure) {
258		if _, err := url.Parse(route.Upstream); err != nil {
259			// Config validation already rejected this.
260			return "", failuref("invalid_config", "route %q has an invalid upstream: %v", route.ID, err)
261		}
262	
263		var remainder string
264		switch {
265		case route.PathPrefix == "/":
266			// Root keeps the whole following path; "/" itself has an empty remainder.
267			if path != "/" {
268				remainder = path
269			}
270		default:
271			remainder = path[len(route.PathPrefix):] // "" or "/...", boundary is a literal slash
272		}
273	
274		// Slice the validated upstream raw so nothing outside the junction is
275		// normalized or re-escaped (scheme://[userinfo@]host[/base-path]).
276		schemeEnd := strings.Index(route.Upstream, "://")
277		tail := route.Upstream[schemeEnd+3:]
278		hostPart, basePath := tail, ""
279		if i := strings.IndexByte(tail, '/'); i >= 0 {
280			hostPart, basePath = tail[:i], tail[i:]
281		}
282		joined := strings.TrimSuffix(basePath, "/")
283		if remainder == "" {
284			joined += "/" // the junction slash is kept even with no remaining path
285		} else {
286			joined += remainder
287		}
288	
289		result := route.Upstream[:schemeEnd+3] + hostPart + joined
290		if i := strings.IndexByte(target, '?'); i >= 0 {
291			result += "?" + target[i+1:] // raw query: duplicates, empty values and order preserved
292		}
293		return result, nil
294	}
295	
296	// isToken reports whether s is an RFC 7230 token, i.e. a legal HTTP method.
297	func isToken(s string) bool {
298		if s == "" {
299			return false
300		}
301		for i := 0; i < len(s); i++ {
302			if !isTokenChar(s[i]) {
303				return false
304			}
305		}
306		return true
307	}
308	
309	func isTokenChar(c byte) bool {
310		switch {
311		case c >= 'a' && c <= 'z', c >= 'A' && c <= 'Z', c >= '0' && c <= '9':
312			return true
313		}
314		switch c {
315		case '!', '#', '$', '%', '&', '\'', '*', '+', '-', '.', '^', '_', '`', '|', '~':
316			return true
317		}
318		return false
319	}
320	
321	// validPercentEscapes checks that every "%' is followed by two hex digits.
322	// Matching and joining stay on raw strings, but malformed escapes are rejected
323	// up front for both prefixes and request targets.
324	func validPercentEscapes(s string) bool {
325		for i := 0; i < len(s); i++ {
326			if s[i] != '%' {
327				continue
328			}
329			if i+2 >= len(s) || !isHex(s[i+1]) || !isHex(s[i+2]) {
330				return false
331			}
332			i += 2
333		}
334		return true
335	}
336	
337	func isHex(c byte) bool {
338		switch {
339		case c >= '0' && c <= '9', c >= 'a' && c <= 'f', c >= 'A' && c <= 'F':
340			return true
341		}
342		return false
343	}
344

