360	func TestResolutionJSONShape(t *testing.T) {
361		cfg := mustConfig(t, `{"routes":[{"id":"r1","methods":["GET"],"pathPrefix":"/","upstream":"http://h"}]}`)
362		res := resolveJSON(t, cfg, `{"method":"GET","target":"/p?q=1"}`)
363		out, err := json.Marshal(res)
364		if err != nil {
365			t.Fatal(err)
366		}
367		if string(out) != `{"routeId":"r1","upstreamURL":"http://h/p?q=1"}` {
368			t.Fatalf("json = %s", out)
369		}
