371	
372	func TestFailureJSONShape(t *testing.T) {
373		f := failuref("route_conflict", "boom")
374		f.Candidates = []string{"b", "a"}
375		out, _ := json.Marshal(f)
376		var got map[string]any
377		if err := json.Unmarshal(out, &got); err != nil {
378			t.Fatal(err)
379		}
380		if got["code"] != "route_conflict" || got["reason"] != "boom" {
381			t.Fatalf("unexpected json: %s", out)
382		}
